import {escapeHTML as esc} from './component-markings.mjs';
import {boardThumbnail} from './board-thumbnail.mjs';
import {caseStages,briefFor,createCase,validateCase,narratedGuides} from './atlas-cases.mjs';
export function mountAtlas(api){
 const $=id=>document.getElementById(id);document.body.classList.add('atlasApp');document.title='Circuit Atlas · Entiende la placa';
 const brand=document.querySelector('.brand');brand.innerHTML='<span class="atlasBrandMark">C<span>↗</span></span><span>CIRCUIT <b>ATLAS</b><small>Electrónica, con contexto.</small></span>';
 const labels={home:'Mi espacio',course:'Ruta de estudio',library:'Atlas de placas',lab:'Caso abierto',scope:'Instrumentos',projects:'Archivo'};for(const [key,label]of Object.entries(labels))if($('nav'+key))$('nav'+key).textContent=label;
 document.querySelector('.sidebarKicker').textContent='TU MESA DE ESTUDIO';document.querySelector('.sidebarFoot').innerHTML='CIRCUIT ATLAS<br><small>Observar. Comprender. Comprobar.</small>';document.querySelector('.studioVersion').textContent='ATLAS / 01';
 let sessions={};try{const data=JSON.parse(api.storage.getItem('circuitlab-atlas-cases-v1')||'{}');for(const [id,s]of Object.entries(data)){try{const v=validateCase(s,api.boards);sessions[id]=v;}catch{}}}catch{}
 let current=null;const save=()=>{if(!current)return;current.updated=new Date().toISOString();sessions[current.board]=current;try{api.storage.setItem('circuitlab-atlas-cases-v1',JSON.stringify(sessions));$('atlasCaseStatus').textContent='Guardado en este navegador';}catch{$('atlasCaseStatus').textContent='No se pudo guardar. Exporta el caso para conservarlo.';}};
 function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 const home=$('homePage');home.innerHTML=`<section class="atlasWelcome"><div><span class="atlasEyebrow">TU PRÓXIMA CONEXIÓN</span><h1>No memorices una placa.<br><em>Aprende a entenderla.</em></h1><p>Un recorrido desde la primera resistencia hasta el razonamiento de diagnóstico. Mira, conecta ideas y comprueba lo que has entendido.</p><div class="atlasActions"><button id="atlasContinue" class="academyPrimary">Seguir mi aprendizaje <span>↗</span></button><button id="atlasChoose">Elegir un caso</button></div><div class="atlasNumbers"><span><b>${api.boards.length}</b> placas explorables</span><span><b>${api.boards.filter(b=>!b.educational&&!b.representative).length}</b> diseños CAD originales</span><span><b>4</b> pasos para razonar</span></div></div><div class="atlasCover">${boardThumbnail(api.boards.find(b=>b.id==='computer')||api.boards[0])}<span class="atlasCoverTag">ANATOMÍA DE UNA PLACA</span><p>La complejidad se vuelve legible<br>cuando aprendes a separar funciones.</p></div></section><section class="atlasLearningStrip"><div><span>01</span><b>Observar</b><small>Reconocer lo que ves.</small></div><div><span>02</span><b>Entender</b><small>Relacionar piezas y funciones.</small></div><div><span>03</span><b>Comprobar</b><small>Buscar una evidencia.</small></div><div><span>04</span><b>Explicar</b><small>Sostener una conclusión.</small></div></section><div class="atlasSectionTitle"><div><span class="atlasEyebrow">APRENDE CON UN PROPÓSITO</span><h2>Una placa. Una pregunta.</h2></div><button id="atlasAll">Ver todo el atlas ↗</button></div><div class="atlasCaseCards">${['mosfet','lipo-charger','computer'].map(id=>{const b=api.boards.find(b=>b.id===id),c=briefFor(b);return `<button class="atlasCaseCard" data-case="${id}"><div>${boardThumbnail(b)}</div><section><span>${esc(c.level)} · ${c.minutes} min</span><h3>${esc(c.title)}</h3><p>${esc(c.question)}</p><b>Abrir caso <i>↗</i></b></section></button>`;}).join('')}</div><section class="atlasAudioShelf"><div><span class="atlasEyebrow">IDEAS PARA LLEVAR CONTIGO</span><h2>Escucha. Pausa. Comprende.</h2><p>Explicaciones breves con el texto siempre disponible.</p></div><div>${narratedGuides.map((g,i)=>`<button data-guide="${g.id}"><span>0${i+1}</span><b>${esc(g.title)}</b><i>▶</i></button>`).join('')}</div></section><section class="atlasRecent"><div class="atlasSectionTitle"><h2>Tu cuaderno de casos</h2><label class="projectImport">Importar caso<input id="atlasImport" type="file" accept=".json,application/json"></label></div><div id="atlasCaseHistory"></div><p id="atlasImportStatus" role="status"></p></section><div id="studioRecent" hidden></div>`;
 $('atlasContinue').onclick=()=>{api.show('course');$('planResume')?.click();};$('atlasChoose').onclick=()=>api.show('library');$('atlasAll').onclick=()=>api.show('library');home.querySelectorAll('[data-case]').forEach(btn=>btn.onclick=()=>start(btn.dataset.case));home.querySelectorAll('[data-guide]').forEach(btn=>btn.onclick=()=>openGuide(btn.dataset.guide));
 const catalog=document.createElement('section');catalog.className='atlasCatalog';catalog.innerHTML=`<div class="atlasCatalogHeading"><span class="atlasEyebrow">ELIGE TU OBJETO DE ESTUDIO</span><h1>El atlas de placas.</h1><p>Empieza por una función. Después recorre componentes, pistas y esquemas, con el nivel de fidelidad siempre visible.</p></div><div class="atlasCatalogFilters"><label>Buscar una placa<input id="atlasBoardSearch" type="search" placeholder="Audio, carga, ordenador…"></label><label>Tipo de modelo<select id="atlasBoardKind"><option value="all">Todos los modelos</option><option value="cad">CAD original</option><option value="didactic">Didácticos</option></select></label><span id="atlasBoardCount" role="status"></span></div><div id="atlasBoardGrid"></div><button id="atlasLegacy">Abrir biblioteca de circuitos y referencias ↓</button>`;$('libraryPage').prepend(catalog);
 function renderBoards(){const q=$('atlasBoardSearch').value.toLocaleLowerCase('es'),kind=$('atlasBoardKind').value,boards=api.boards.filter(b=>(kind==='all'||(kind==='cad')===(!b.educational&&!b.representative))&&`${b.title} ${b.domain||''} ${b.blocks.map(g=>g.title).join(' ')}`.toLocaleLowerCase('es').includes(q));$('atlasBoardCount').textContent=boards.length+' placas';$('atlasBoardGrid').innerHTML=boards.map(b=>`<article class="atlasBoardCard"><div>${boardThumbnail(b)}<span class="atlasFidelity">${!b.educational&&!b.representative?'CAD ORIGINAL':'MODELO DIDÁCTICO'}</span></div><section><span>${esc(b.domain||'Electrónica')}</span><h2>${esc(b.title)}</h2><p>${esc(briefFor(b).question)}</p><div class="atlasBoardFacts"><span>${b.elements.length} piezas</span><span>${b.blocks.length} bloques</span><span>${b.nets.length} redes</span></div><button data-case="${b.id}" class="academyPrimary">Estudiar esta placa ↗</button><button data-explore="${b.id}">Explorar libremente</button><details><summary>Qué reproduce este modelo</summary><p>${esc(b.fidelity||'Modelo de estudio con cuerpos aproximados.')}</p></details></section></article>`).join('')||'<p class="atlasEmpty">No hay placas con esos filtros.</p>';$('atlasBoardGrid').querySelectorAll('[data-case]').forEach(btn=>btn.onclick=()=>start(btn.dataset.case));$('atlasBoardGrid').querySelectorAll('[data-explore]').forEach(btn=>btn.onclick=()=>{current=null;casePanel.hidden=true;api.openBoard(btn.dataset.explore);});}
 $('atlasBoardSearch').oninput=renderBoards;$('atlasBoardKind').onchange=renderBoards;$('atlasLegacy').onclick=()=>{$('libraryPage').classList.toggle('showLegacy');$('atlasLegacy').textContent=$('libraryPage').classList.contains('showLegacy')?'Cerrar biblioteca complementaria ↑':'Abrir biblioteca de circuitos y referencias ↓';};renderBoards();
 const casePanel=document.createElement('section');casePanel.className='atlasCasePanel';casePanel.hidden=true;$('labPage').prepend(casePanel);
 function renderCase(){if(!current)return;const b=api.boards.find(b=>b.id===current.board),brief=briefFor(b),stage=caseStages[current.stage];casePanel.innerHTML=`<div class="atlasCaseHeading"><div><span class="atlasEyebrow">CASO GUIADO · ${esc(brief.level)}</span><h1>${esc(brief.title)}</h1><p>${esc(brief.question)}</p></div><button id="atlasCaseExport">Exportar caso</button></div><nav class="atlasStages" aria-label="Etapas del caso">${caseStages.map((s,i)=>`<button data-stage="${i}" aria-current="${i===current.stage?'step':'false'}"><span>0${i+1}</span>${s.name}<small>${current.notes[i].trim()?'●':'○'}</small></button>`).join('')}</nav><div class="atlasCaseContent"><div><span class="atlasEyebrow">${esc(stage.name)}</span><h2>${esc(stage.prompt)}</h2><p>${esc(stage.help)}</p><details open><summary>En esta placa</summary><p>${esc(current.stage===0?brief.observe:current.stage===1?brief.concept:current.stage===2?brief.evidence:brief.limit)}</p></details><button id="atlasCaseBlock">Ver bloque de referencia ↗</button></div><div><label for="atlasCaseNote">${current.stage===3?'Tu conclusión razonada':'Tu observación / hipótesis'}</label><textarea id="atlasCaseNote" maxlength="6000" rows="4" placeholder="Describe qué ves y qué evidencia lo respalda…">${esc(current.notes[current.stage])}</textarea><div class="atlasCaseFooter"><small id="atlasCaseStatus" role="status">${current.complete?'Caso documentado':'Tus notas se guardan en este navegador'}</small><button id="atlasCaseNext" class="academyPrimary">${current.stage===3?'Documentar conclusión':'Guardar y continuar →'}</button></div></div></div>`;
 casePanel.querySelectorAll('[data-stage]').forEach(btn=>btn.onclick=()=>{current.stage=Number(btn.dataset.stage);save();renderCase();});$('atlasCaseNote').oninput=e=>{current.notes[current.stage]=e.target.value;current.complete=false;save();};$('atlasCaseNext').onclick=()=>{if(!current.notes[current.stage].trim()){$('atlasCaseStatus').textContent='Escribe al menos una observación antes de continuar.';return;}if(current.stage<3)current.stage++;else if(current.notes.some(n=>!n.trim())){$('atlasCaseStatus').textContent='Faltan notas en alguna etapa. Puedes volver con los botones superiores.';return;}else current.complete=true;save();renderCase();renderHistory();};$('atlasCaseExport').onclick=()=>download({format:'circuit-atlas-case',case:current},'circuit-atlas-'+b.id+'.json');$('atlasCaseBlock').onclick=()=>{if(brief.focus)api.selectBlock(brief.focus);document.querySelector('.viewer').scrollIntoView({behavior:'smooth',block:'start'});};}
 function start(id){const b=api.boards.find(b=>b.id===id);if(!b)return;api.openBoard(id);current=sessions[id]||createCase(b);casePanel.hidden=false;renderCase();renderHistory();}
 function renderHistory(){$('atlasCaseHistory').innerHTML=Object.values(sessions).sort((a,b)=>b.updated.localeCompare(a.updated)).map(s=>`<button data-resume="${s.board}"><span>${s.complete?'✓':'◌'}</span><div><b>${esc(briefFor(api.boards.find(b=>b.id===s.board)).title)}</b><small>${s.complete?'Documentado':caseStages[s.stage].name+' · en curso'}</small></div><i>↗</i></button>`).join('')||'<p class="atlasEmpty">Tu primer caso aparecerá aquí cuando guardes una observación.</p>';$('atlasCaseHistory').querySelectorAll('[data-resume]').forEach(btn=>btn.onclick=()=>start(btn.dataset.resume));}
 $('atlasImport').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>50000)throw Error('El archivo supera el tamaño de un caso.');const v=JSON.parse(await file.text());if(v.format!=='circuit-atlas-case')throw Error('Formato de caso desconocido.');current=validateCase(v.case,api.boards);renderCase();save();renderHistory();$('atlasImportStatus').textContent='Caso importado.';}catch(err){$('atlasImportStatus').textContent=err.message;}};
 document.addEventListener('circuitlab:page',e=>{if(e.detail==='home')renderHistory();});document.getElementById('boardSelect').addEventListener('change',()=>{if(current&&api.board().id!==current.board){current=null;casePanel.hidden=true;}});
 function openGuide(id){const g=narratedGuides.find(g=>g.id===id),d=document.createElement('dialog');d.className='atlasGuide';d.innerHTML=`<button class="atlasGuideClose" aria-label="Cerrar explicación">×</button><span class="atlasEyebrow">UN CONCEPTO, SIN PRISA</span><h2>${esc(g.title)}</h2><p>${esc(g.text)}</p><div class="atlasGuideAudio"><button class="academyPrimary" id="atlasReadGuide">Escuchar explicación</button><button id="atlasStopGuide">Detener</button><small id="atlasVoiceStatus" role="status">Voz sintética del dispositivo. Narración de estudio disponible cuando se incorpora al proyecto.</small></div>`;document.body.append(d);let audio=null;d.querySelector('.atlasGuideClose').onclick=()=>d.close();d.addEventListener('close',()=>{api.stopGuide?.();d.remove();},{once:true});d.querySelector('#atlasReadGuide').onclick=async()=>{api.readGuide?.(g,d);};d.querySelector('#atlasStopGuide').onclick=()=>api.stopGuide?.();d.showModal();}
 renderHistory();api.show('home');return {start,renderBoards,current:()=>current};
}
